    (43, 'GLOVES', 1, 0, 5, 0, 8, 0, 'Wind Striker,Earth Sentinel,Ki Vanguard'),
    (44, 'GLOVES', 15, 0, 10, 0, 16, 0, 'Wind Striker,Earth Sentinel,Ki Vanguard'),
    (45, 'GLOVES', 35, 0, 16, 0, 25, 0, 'Wind Striker,Earth Sentinel,Ki Vanguard'),
    (46, 'BOOTS', 1, 0, 0, 2, 0, 2, 'Wind Striker,Earth Sentinel,Ki Vanguard'),
    (47, 'BOOTS', 15, 0, 0, 4, 0, 3, 'Wind Striker,Earth Sentinel,Ki Vanguard'),
    (48, 'BOOTS', 35, 0, 0, 6, 0, 5, 'Wind Striker,Earth Sentinel,Ki Vanguard'),
    (49, 'RING', 1, 2, 1, 1, 5, 1, 'Wind Striker,Earth Sentinel,Ki Vanguard'),
    (50, 'RING', 15, 4, 2, 2, 10, 2, 'Wind Striker,Earth Sentinel,Ki Vanguard'),
    (51, 'RING', 35, 7, 3, 3, 16, 3, 'Wind Striker,Earth Sentinel,Ki Vanguard'),
    (52, 'AMULET', 1, 0, 3, 0, 6, 1, 'Wind Striker,Earth Sentinel,Ki Vanguard'),
    (53, 'AMULET', 15, 0, 6, 0, 12, 2, 'Wind Striker,Earth Sentinel,Ki Vanguard'),
    (54, 'AMULET', 35, 0, 10, 0, 20, 3, 'Wind Striker,Earth Sentinel,Ki Vanguard')
ON CONFLICT (item_id) DO UPDATE
SET
    slot = EXCLUDED.slot,
    required_level = EXCLUDED.required_level,
    atk_bonus = EXCLUDED.atk_bonus,
    def_bonus = EXCLUDED.def_bonus,
    speed_bonus = EXCLUDED.speed_bonus,
    hp_bonus = EXCLUDED.hp_bonus,
    energy_bonus = EXCLUDED.energy_bonus,
    allowed_classes = EXCLUDED.allowed_classes;

UPDATE public.items i
SET equipment_id = e.id
FROM public.equipments e
WHERE e.item_id = i.id
  AND i.type = 'EQUIPMENT';
